package com.secwatch.config;
import com.secwatch.security.JwtFilter;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.List;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain filter(HttpSecurity http,JwtFilter jwt,@Value("${app.cors-origin}") String origin)throws Exception {http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOrigins(List.of(origin));x.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));x.setAllowedHeaders(List.of("Authorization","Content-Type"));x.setAllowCredentials(true);return x;})).headers(h->h.frameOptions(f->f.sameOrigin())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((q,s,x)->{s.setStatus(401);s.setContentType("application/json");s.getWriter().write("{\"status\":401,\"message\":\"Authentification requise ou session expirée.\"}");}).accessDeniedHandler((q,s,x)->{s.setStatus(403);s.setContentType("application/json");s.getWriter().write("{\"status\":403,\"message\":\"Accès interdit.\"}");})).authorizeHttpRequests(a->a.requestMatchers("/auth/**","/h2-console/**").permitAll().requestMatchers("/api/**").authenticated().anyRequest().permitAll()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class);return http.build();}
}
